import 'package:drift/drift.dart';
import 'package:drift_flutter/drift_flutter.dart';
import 'package:estudicards/core/db/tables.dart';

export 'tables.dart';

// Generated by `dart run build_runner build`; not committed (see README).
part 'app_database.g.dart';

/// The app's SQLite database.
///
/// Drift reads the `tables` list and generates the `_$AppDatabase` base class
/// with one accessor per table (`db.projects`, `db.decks`…).
@DriftDatabase(
  tables: [
    Projects,
    Decks,
    Cards,
    CardOptions,
    CardStats,
    StudySessions,
    SessionDecks,
    Attempts,
    Settings,
  ],
)
class AppDatabase extends _$AppDatabase {
  /// Opens `estudicards.sqlite` in the app documents folder (SPEC §3.4).
  /// Tests pass an in-memory connection instead: `NativeDatabase.memory()`.
  new([QueryExecutor? executor])
    : super(executor ?? driftDatabase(name: 'estudicards'));

  /// Bump this number on every schema change and add its migration.
  @override
  int get schemaVersion => 1;

  /// A migration tells Drift how to create the tables the first time and,
  /// later, how to upgrade an old database when `schemaVersion` grows.
  @override
  MigrationStrategy get migration => MigrationStrategy(
    beforeOpen: (details) async {
      // SQLite ignores foreign keys unless they are switched on for every
      // connection. Without this, deleting a card would leave its options,
      // stats and attempts behind.
      await customStatement('PRAGMA foreign_keys = ON');
    },
  );
}
